type CardBinding = { tag: string; className: string; text: string; index: number; initial: Values; animate: Values; transition: Values };
type VisualSpec = { kind: string; host: { tag: string; className: string }; props: DotOptions & { meteors?: { width: number; height: number; path: string; repeat?: number; delay?: number; direction?: string }[]; skip?: number } };
type CardState = { title?: string; bindings: CardBinding[]; visuals: VisualSpec[] };
type CardSpec = { on: CardState; off: CardState };
function findExact(root: Element, tag: string, className: string, text?: string, ordinal = 0): HTMLElement | SVGElement | undefined {
  const matches = Array.from(root.querySelectorAll<HTMLElement | SVGElement>(tag)).filter(node => (node.getAttribute('class') || '') === className);
  const direct = text ? matches.filter(node => Array.from(node.childNodes).filter(child => child.nodeType === 3).map(child => child.textContent).join('') === text) : matches;
  return (direct.length ? direct : matches)[ordinal];
}
